(()=>{"use strict";const fmt=n=>Number(n).toLocaleString(typeof window<"u"&&window.CMI18n?window.CMI18n.formatLocale:"en-US",{maximumFractionDigits:6}),$=id=>document.getElementById(id);function compute(dist,fuel){const l100=fuel/dist*100,kmL=fuel>0?dist/fuel:null,miles=dist/1.609344,mpgUS=fuel>0?miles/(fuel/3.785411784):null,mpgUK=fuel>0?miles/(fuel/4.54609):null;return{l100,kmL,mpgUS,mpgUK}}function get(){const v={};return document.querySelectorAll("input,select").forEach(e=>{v[e.id]=e.tagName==="SELECT"?e.value:parseFloat(e.value)}),v}function render(){const v=get();if(!(Number.isFinite(v.dist)&&v.dist>0&&Number.isFinite(v.fuel)&&v.fuel>=0)){$("result").textContent="\u2014",$("chipBase").textContent="\u2014",$("chipInv").textContent="\u2014",$("tblRows").innerHTML="",["bar100","bar300","bar600"].forEach(id=>{$(id).style.width="0%"}),["bar100Val","bar300Val","bar600Val"].forEach(id=>{$(id).textContent="\u2014"});const vd2=$("verdict");vd2.className="verdict bad",$("verdictText").textContent="Enter a distance above zero and fuel used at zero or above.",window.__summary="";return}const r=compute(v.dist,v.fuel);$("result").textContent=fmt(r.l100)+" L/100km",$("chipBase").textContent=r.kmL!==null?fmt(r.kmL)+" km/L":"\u2014 (no fuel used)",$("chipInv").textContent=r.mpgUS!==null?fmt(r.mpgUS)+" US MPG":"\u2014",$("tblRows").innerHTML="<tr><td>Litres per 100 km</td><td class='num'>"+fmt(r.l100)+"</td></tr><tr><td>Kilometres per litre</td><td class='num'>"+(r.kmL!==null?fmt(r.kmL):"\u2014")+"</td></tr><tr><td>US miles per gallon</td><td class='num'>"+(r.mpgUS!==null?fmt(r.mpgUS):"\u2014")+"</td></tr><tr><td>UK miles per gallon</td><td class='num'>"+(r.mpgUK!==null?fmt(r.mpgUK):"\u2014")+"</td></tr>";const vd=$("verdict");vd.className="verdict",$("verdictText").textContent=r.l100<=6?"Efficient on these numbers: under 6 L/100km is economical for most petrol cars.":r.l100<=9?"Mid-range consumption: typical for a family petrol car in mixed driving.":"High consumption on these numbers: above 9 L/100km is thirsty for a modern car \u2014 check driving mix and load before comparing models.",window.__summary="Fuel economy: "+fmt(v.dist)+" km on "+fmt(v.fuel)+" L = "+fmt(r.l100)+" L/100km, "+(r.kmL!==null?fmt(r.kmL)+" km/L":"")+", "+(r.mpgUS!==null?fmt(r.mpgUS)+" US MPG":"")+".";const f100=r.l100*1,f300=r.l100*3,f600=r.l100*6;$("bar100Val").textContent=fmt(f100)+" L",$("bar300Val").textContent=fmt(f300)+" L",$("bar600Val").textContent=fmt(f600)+" L";const mx=Math.max(f600,1e-6);$("bar100").style.width=f100/mx*100+"%",$("bar300").style.width=f300/mx*100+"%",$("bar600").style.width=f600/mx*100+"%"}document.querySelectorAll("input,select").forEach(e=>e.addEventListener("input",render)),render()})();
